let centreX,centreY,rows,cols,originX,originY,animatedImg,w=window.innerWidth,h=window.innerHeight,defScale=15,circleScale=defScale,defSpace=8,gridSpace=defSpace,defSample=2,pixelSample=defSample;const halftoneColour="#0d0c1d",backgroundColour="#f8eee6";let animationProgress=0,animationSpeed=.005,expanding=!0,isPlaying=!1;function setup(){createCanvas(w,h),frameRate(60),noLoop(),loadImage("./assets/WordmarkAnimation1.png",e=>{animatedImg=e,centreImage(),loop()});let e=document.querySelector("#playPauseButton");e.addEventListener("click",()=>{e.textContent=(isPlaying=!isPlaying)?"Pause":"Play"});let a=document.querySelector("#animationSlider");a.addEventListener("input",()=>{isPlaying||(animationProgress=a.value/100,redraw())})}function draw(){background("#f8eee6"),animatedImg&&(noStroke(),fill("#0d0c1d"),centreImage(),drawHalftone(),isPlaying&&(updateAnimation(),document.querySelector("#animationSlider").value=100*animationProgress))}function windowResized(){w=window.innerWidth,h=window.innerHeight,resizeCanvas(w,h),centreImage()}function centreImage(){animatedImg&&(cols=floor(animatedImg.width/pixelSample),rows=floor(animatedImg.height/pixelSample),centreX=w/2-cols*gridSpace/2,centreY=h/2-rows*gridSpace/2)}function drawHalftone(){if(animatedImg)for(let e=0;e<cols;e++)for(let a=0;a<rows;a++){let n=alpha(animatedImg.get(e*pixelSample,a*pixelSample));if(n>79){let i=map(n,80,255,0,1);circle(e*gridSpace+centreX,a*gridSpace+centreY,circleScale*i)}}}function updateAnimation(){expanding?(animationProgress+=animationSpeed)>=1&&(animationProgress=1,expanding=!1):(animationProgress-=animationSpeed)<=0&&(animationProgress=0,expanding=!0);let e=easeInOutCubic(animationProgress);circleScale=map(.9*e,0,1,0*defScale,1.3*defScale),gridSpace=map(e,0,1,1.3*defSpace,1.5*defSpace)}function easeInOutCubic(e){return e<.5?4*e*e*e:1-pow(-2*e+2,3)/2}